/* Agile Orbit — techniques, models and tools inside Agile Coaching topics */
(function(){
  'use strict';

  const library={
    'stakeholder-coaching':[
      {name:'Stake × Influence Map',type:'FRAMEWORK',summary:'Map stakeholders by how much they are affected by the outcome and how much influence they have over it.',helps:'Choose an engagement strategy instead of treating every stakeholder the same.',steps:['List people or groups who can materially affect, decide, enable, block or experience the outcome.','Estimate each stakeholder’s stake in the outcome and influence over decisions.','Discuss where early involvement is essential and where simple visibility is enough.','Review the map when decisions, ownership or context change.'],example:'A compliance leader has high influence and high stake in a regulated onboarding change, so the team involves them during discovery rather than waiting for final sign-off.',watch:'The map is a conversation aid, not a label for “good” or “difficult” stakeholders.'},
      {name:'Engagement Strategy Canvas',type:'CANVAS',summary:'Turn the stakeholder map into explicit choices about who to involve, consult, inform or keep close.',helps:'Reduce late surprises and unclear expectations.',steps:['Pick the stakeholders that matter most to the current outcome.','For each, state the decision or feedback you need from them.','Choose the interaction: involve, consult, inform or monitor.','Set the earliest useful moment for that interaction.'],example:'Instead of inviting an operations stakeholder only to Sprint Review, the team brings them into refinement when operational constraints can still shape the solution.',watch:'More engagement is not always better. Involve people where their contribution can change the decision.'}
    ],
    'psychological-safety':[
      {name:'Leader Goes Last',type:'TECHNIQUE',summary:'When hierarchy could anchor the room, ask the senior person to share their view after others have contributed.',helps:'Reduce conformity pressure and increase independent thinking.',steps:['Frame the decision or question clearly.','Invite individual input before the most senior voice speaks.','Ask the leader to listen and clarify rather than react while others contribute.','Compare perspectives before converging.'],example:'In a risk review, the engineering manager listens while team members surface concerns first, then adds their perspective.',watch:'This is not about silencing leaders. It is about preventing their early view from becoming the default answer.'},
      {name:'Silent Writing Before Discussion',type:'TECHNIQUE',summary:'Give everyone time to think and write before group discussion begins.',helps:'Increase participation from quieter members and reduce dominance effects.',steps:['Ask one focused question.','Give 2–5 minutes for silent individual writing.','Share or cluster responses before debating them.','Discuss patterns, differences and missing views.'],example:'Before a retrospective discussion, everyone writes one risk and one assumption before anyone speaks.',watch:'Silent writing creates input; facilitation is still needed to make the discussion safe and useful.'}
    ],
    'team-effectiveness':[
      {name:'Working Agreements',type:'CANVAS',summary:'Create explicit agreements about how the team collaborates, decides, communicates and handles conflict.',helps:'Turn vague expectations into observable team behaviour.',steps:['Ask what the team needs from one another to succeed.','Group recurring needs into a small set of behavioural agreements.','Make each agreement specific enough to observe.','Review agreements when they stop helping.'],example:'“We raise a blocker within one working day” is more actionable than “communicate better”.',watch:'A working agreement that cannot be challenged or changed becomes another rulebook.'},
      {name:'Swarming on Outcomes',type:'TECHNIQUE',summary:'Shift from individual task ownership to temporary collective focus on the most important blocked or aging work.',helps:'Reduce hero dependency, hand-offs and excess WIP.',steps:['Identify the highest-value item that needs help to finish.','Ask what skills or decisions are missing.','Bring the smallest useful group around that work.','Stop swarming when the constraint is resolved and learning is shared.'],example:'Instead of starting three new stories while testing is blocked, developers and testers swarm on the oldest item.',watch:'Swarming should not become a permanent meeting or indiscriminate “everyone on everything”.'}
    ],
    'communication-behaviour':[
      {name:'DiSC',type:'MODEL',summary:'A behavioural-awareness model that describes patterns often associated with Dominance, Influence, Steadiness and Conscientiousness.',helps:'Create hypotheses about pace, directness, sociability, detail and risk preferences so communication can adapt.',steps:['Observe behaviour rather than assuming a fixed personality type.','Notice whether the person seems to prefer speed, social interaction, stability or detail.','Adapt message structure and interaction style to the situation.','Check your hypothesis directly instead of treating the model as truth.'],example:'For a detail-oriented stakeholder, provide evidence and decision criteria before asking for sign-off; for a fast-paced stakeholder, lead with the decision and key trade-off.',watch:'Never use DiSC to stereotype people or explain every behaviour. Context and individual preference matter.'},
      {name:'Observation → Interpretation → Check',type:'TECHNIQUE',summary:'Separate what you actually observed from the story you are telling yourself about it.',helps:'Reduce avoidable interpersonal conflict and attribution errors.',steps:['State the observable behaviour without judgment.','Name your interpretation privately.','Generate at least one alternative explanation.','Ask a curious question to test the interpretation.'],example:'Observation: “They did not respond for two days.” Interpretation: “They do not care.” Check: “What got in the way of responding?”',watch:'The goal is not to suppress judgment, but to avoid treating an untested interpretation as fact.'}
    ],
    'conflict-coaching':[
      {name:'Thomas-Kilmann Conflict Modes',type:'MODEL',summary:'A conflict model using two dimensions—assertiveness and cooperativeness—to describe five possible modes: Competing, Collaborating, Compromising, Avoiding and Accommodating.',helps:'Choose a conflict response intentionally instead of assuming one mode is always best.',steps:['Clarify the issue, stakes and time pressure.','Consider how strongly each side needs to assert its concern.','Consider how much cooperation is required for a workable outcome.','Choose or shift mode deliberately as the situation changes.'],example:'A production incident may require temporary Competing/decisive action; a recurring architecture disagreement may benefit from Collaborating; a low-stakes preference may be Accommodated.',watch:'Collaborating is not automatically superior. Different situations justify different modes.'},
      {name:'5 Levels of Conflict',type:'MODEL',summary:'A simple escalation lens: 1 Problem to Solve → 2 Disagreement → 3 Contest → 4 Crusade → 5 World War.',helps:'Recognise when conflict has moved from solving an issue toward winning, protecting camps or damaging the other side.',steps:['Identify the current level from language and behaviour, not the original topic.','At Levels 1–2, facilitate direct problem solving and shared facts.','At Level 3, slow the interaction, clarify rules and reduce win/lose dynamics.','At Levels 4–5, prioritise containment, boundaries, mediation and leadership support before attempting normal problem solving.'],example:'“How do we solve this?” suggests Level 1; “They always do this” may signal movement toward Level 3; coalition-building against the other group suggests escalation beyond the original issue.',watch:'Do not use levels to diagnose people. Use them to choose an intervention appropriate to the intensity of the interaction.'},
      {name:'Interest-Based Reframing',type:'TECHNIQUE',summary:'Move the conversation from stated positions to the needs, risks or outcomes each side is trying to protect.',helps:'Find options that are invisible when both sides argue only for their preferred solution.',steps:['Ask each side to state their position.','Ask what important need, concern or risk sits underneath it.','Restate the conflict in terms of both sets of interests.','Generate options that address the interests before evaluating solutions.'],example:'“We need two weeks” versus “We need Friday” becomes “engineering needs enough time to protect reliability while product needs evidence before a regulatory deadline”.',watch:'Reframing does not remove real trade-offs. Sometimes a decision still has to be made.'}
    ],
    'mindset-learning':[
      {name:'Fixed vs Growth Mindset',type:'MODEL',summary:'A lens for noticing whether capability is treated as fixed or developable through effort, strategy, feedback and learning.',helps:'Shift from proving competence toward increasing competence.',steps:['Notice language such as “I am not good at this” or “we always fail at this”.','Reframe the issue as a capability that can be developed.','Choose a small practice or feedback loop.','Review learning rather than only success/failure.'],example:'Replace “the team cannot estimate” with “what would help the team improve how it reasons about uncertainty?”',watch:'Growth mindset is not a reason to ignore structural barriers or overload.'},
      {name:'Learning Hypothesis',type:'TECHNIQUE',summary:'Turn an improvement idea into a testable belief with observable evidence.',helps:'Make learning explicit and prevent retrospective actions from becoming unchecked habits.',steps:['Write what you believe is happening.','Choose one small change.','State what evidence you expect if the belief is right.','Set a review date and decide keep, adapt or stop.'],example:'“We believe review queues are caused by large pull requests. If we reduce batch size, median review time should fall within two Sprints.”',watch:'A hypothesis needs evidence that can influence the next decision.'}
    ],
    'change-fatigue':[
      {name:'Change Saturation Map',type:'CANVAS',summary:'Visualise all significant changes currently hitting the same people or teams.',helps:'See cumulative change demand rather than evaluating each initiative in isolation.',steps:['List active and upcoming changes affecting the group.','Estimate effort to understand, learn and adopt each one.','Mark timing overlaps and shared dependencies.','Pause, sequence, combine or stop lower-value changes.'],example:'A team facing a new operating model, tooling migration, AI rollout and reorganisation in the same quarter can see the combined absorption load.',watch:'Do not treat the map as proof that change must stop; use it to make capacity trade-offs visible.'},
      {name:'Change Capacity Check',type:'TECHNIQUE',summary:'Before launching another change, ask whether the receiving system has attention, trust, skills and time to absorb it.',helps:'Pace change to the system’s actual capacity.',steps:['Assess current workload and concurrent change demand.','Ask what prior changes are still stabilising.','Identify capability or support gaps.','Agree what must stop or reduce to create capacity.'],example:'Leadership delays a process rollout until teams complete a high-risk platform migration rather than layering both together.',watch:'“Capacity” includes emotional and cognitive load, not only calendar availability.'}
    ],

    'define-product':[
      {name:'Product Boundary Canvas',type:'CANVAS',summary:'Clarify users, customers, value, responsibilities and what sits inside or outside the product boundary.',helps:'Prevent component optimisation and mixed backlogs with no coherent product outcome.',steps:['Name the primary users and customers.','State the enduring problem or value the product exists to address.','List capabilities that belong inside the boundary.','List adjacent services or responsibilities that sit outside.'],example:'A risk platform may include scoring and decision services but exclude the downstream case-management product that consumes those decisions.',watch:'Do not define the product around today’s org chart if value flows differently.'},
      {name:'Value Exchange Map',type:'MODEL',summary:'Map who gives and receives value around a product.',helps:'Reveal that different stakeholders may value different outcomes.',steps:['List users, customers and key stakeholders.','For each, identify what value they receive.','Identify what the product needs from them—data, payment, trust, adoption or decisions.','Use the map to sharpen goals and feedback loops.'],example:'A compliance tool creates value for investigators through faster triage, for the bank through reduced risk, and for regulators through traceability.',watch:'Value is contextual; avoid reducing every exchange to revenue.'}
    ],
    'product-role-clarity':[
      {name:'Product Quadrant',type:'MODEL',summary:'A practitioner lens for discussing how product strategy, product ownership, project/delivery coordination and analysis differ while still collaborating.',helps:'Create a conversation about role focus and decision boundaries.',steps:['List the recurring decisions in your product system.','Map which role currently owns, advises or executes each decision.','Compare the pattern with the intended accountability.','Resolve gaps where accountability exists without authority.'],example:'The Product Owner may own backlog ordering while product strategy remains with a Product Manager; delivery coordination should not silently take over value decisions.',watch:'Use the quadrant as a discussion aid, not an official Scrum role model.'},
      {name:'Decision Rights Map',type:'CANVAS',summary:'Make who decides, who advises and who must be informed explicit for recurring decisions.',helps:'Reduce approval queues and accountability ambiguity.',steps:['Take the last five delayed decisions.','For each, name the decider and advisers.','Mark which “approvals” are genuine requirements and which are habits.','Move routine decisions closer to the accountable role where safe.'],example:'Pricing-rule changes may require compliance advice but not compliance ownership of the entire backlog.',watch:'More RACI-like detail is not automatically better; focus on decisions that actually create waiting.'}
    ],
    'outcomes-value':[
      {name:'Activity → Output → Outcome → Value',type:'MODEL',summary:'A causal ladder that distinguishes doing work, producing something, changing behaviour/results and creating benefit.',helps:'Stop treating completed features as proof of success.',steps:['Name the activity the team performs.','Name the output it produces.','Describe the observable outcome expected for users or stakeholders.','State the value created if that outcome matters.'],example:'Activity: build onboarding validation → Output: validation capability released → Outcome: fewer invalid applications → Value: faster onboarding with lower compliance risk.',watch:'The causal links are hypotheses. Measure whether the expected outcome actually follows.'},
      {name:'Outcome Hypothesis',type:'TECHNIQUE',summary:'Express a planned output as a belief about the outcome it should create.',helps:'Connect backlog decisions to evidence.',steps:['State the target user or stakeholder.','State the behaviour/result you expect to change.','Name the output you believe will influence it.','Define evidence and a time horizon.'],example:'“We believe pre-filled KYC data will reduce application abandonment from X to Y within six weeks.”',watch:'Avoid choosing a metric merely because it is easy to measure.'}
    ],
    'product-goals-evidence':[
      {name:'Goal → Evidence Tree',type:'CANVAS',summary:'Connect a Product Goal to observable evidence that would indicate progress.',helps:'Turn broad product direction into inspectable learning.',steps:['Write the desired future state.','List observable outcomes that would indicate movement.','For each outcome, identify leading and lagging evidence.','Use evidence to adapt backlog and strategy.'],example:'Goal: faster trusted onboarding → evidence may include completion time, abandonment, manual-review rate and compliance exceptions.',watch:'Do not confuse the evidence tree with a guaranteed causal model.'}
    ],
    'mvp-experimentation':[
      {name:'Riskiest Assumption Test',type:'TECHNIQUE',summary:'Identify the assumption that could invalidate the idea and test it before heavy investment.',helps:'Learn where uncertainty is highest instead of merely shrinking scope.',steps:['List assumptions about desirability, usability, feasibility and viability.','Rank by uncertainty × impact.','Choose the riskiest assumption.','Design the cheapest credible test that can change a decision.'],example:'Before automating a complex advisory flow, manually simulate it with a small user group to learn whether customers understand the recommendation.',watch:'Do not test trivial assumptions while leaving the critical one untouched.'},
      {name:'MVP Experiment Ladder',type:'FRAMEWORK',summary:'Choose the lightest experiment that can answer the learning question: interview → sketch/prototype → concierge/manual service → limited live capability.',helps:'Avoid building production software before the evidence requires it.',steps:['Define the learning question.','Pick the lowest-cost experiment with credible evidence.','Set a decision threshold.','Escalate to a more expensive experiment only if needed.'],example:'A concierge test can validate demand before building an automated workflow.',watch:'Security, safety and regulatory requirements still apply to experiments.'}
    ],
    'product-discovery':[
      {name:'Assumption Mapping',type:'FRAMEWORK',summary:'Visualise what must be true for an idea to work and prioritise the assumptions that are both important and uncertain.',helps:'Focus discovery on risk rather than on producing more research artifacts.',steps:['List assumptions across desirability, usability, feasibility and viability.','Rate importance and uncertainty.','Place them on a simple matrix.','Test high-importance/high-uncertainty assumptions first.'],example:'For an AI adviser, customer trust in generated recommendations may be a riskier assumption than model-response speed.',watch:'Revisit the map as evidence changes; uncertainty is not static.'},
      {name:'Prototype Before Production',type:'TECHNIQUE',summary:'Use a representation of the experience to learn before committing to production code.',helps:'Reduce solution risk and get user feedback earlier.',steps:['Define the question the prototype must answer.','Build only enough fidelity to answer it.','Put it in front of representative users.','Capture behaviour and decisions, not only opinions.'],example:'Test an investment-dashboard navigation prototype before implementing data pipelines for every view.',watch:'A prototype is evidence for a question, not a promise of the final design.'}
    ],
    'prioritisation-tradeoffs':[
      {name:'WSJF',type:'MODEL',summary:'Weighted Shortest Job First compares Cost of Delay with relative job size to support sequencing discussions.',helps:'Structure trade-offs where value, urgency, risk reduction and effort compete.',steps:['Estimate relative Business Value, Time Criticality and Risk Reduction/Opportunity Enablement.','Sum them as Cost of Delay.','Estimate relative job size.','Compare Cost of Delay ÷ Job Size, then discuss whether the ranking makes sense.'],example:'A smaller regulatory-risk reduction item may rank above a larger feature because delay is costly and the job is relatively small.',watch:'WSJF is relative decision support, not financial truth. Avoid false precision.'},
      {name:'Cost of Delay',type:'MODEL',summary:'Ask how value or risk changes when an item is delayed.',helps:'Make urgency economically meaningful rather than emotional.',steps:['Identify the outcome affected by delay.','Estimate how delay changes value, risk or opportunity.','Compare items using the same relative scale.','Use the conversation to challenge “everything is urgent”.'],example:'A market-window capability may have rapidly increasing delay cost while a cosmetic enhancement may not.',watch:'Cost of Delay can be uncertain; make assumptions explicit.'},
      {name:'Forced Ranking',type:'TECHNIQUE',summary:'Require a true sequence instead of allowing many items to share the same priority.',helps:'Expose trade-offs and opportunity cost.',steps:['Take the candidate list.','Force a top three.','For every inclusion, state what drops below it.','Review when evidence changes.'],example:'If five initiatives are all “P1”, the group must choose which one gets scarce capacity first.',watch:'The point is the conversation, not the permanence of the ranking.'}
    ],
    'customer-feedback':[
      {name:'Decision-Driven Review Questions',type:'TECHNIQUE',summary:'Replace generic “Any feedback?” with questions tied to a decision the product team needs to make.',helps:'Make Sprint Reviews and demos produce usable evidence.',steps:['Name the decision the team faces.','Ask 2–3 specific questions that could influence it.','Show working product or evidence.','Capture what changes because of the feedback.'],example:'Instead of “Do you like it?”, ask “Which exception would prevent your team using this workflow in production?”',watch:'Feedback is useful only if the team is willing and able to adapt.'},
      {name:'Evidence Triangulation',type:'FRAMEWORK',summary:'Combine what people say, what they do and what outcome data shows.',helps:'Avoid over-relying on stakeholder opinion or a single metric.',steps:['Collect qualitative feedback.','Observe behaviour or usage where possible.','Review product/business outcome data.','Look for convergence or contradictions before deciding.'],example:'Users may say a workflow is easy while analytics show high abandonment; the contradiction is a discovery signal.',watch:'Different evidence types answer different questions—do not force them into one score.'}
    ],

    'technical-excellence':[
      {name:'Refactoring',type:'TECHNIQUE',summary:'Change internal design without changing externally observable behaviour so future change becomes safer and easier.',helps:'Reduce the cost of recurring change around actively evolving code.',steps:['Protect behaviour with trustworthy tests.','Make one small structural improvement.','Run feedback immediately.','Repeat continuously around changing areas.'],example:'Extract duplicated validation logic before adding another rule rather than waiting for a large cleanup project.',watch:'Refactoring should be incremental and evidence-backed, not an endless perfection exercise.'},
      {name:'Pair Programming',type:'TECHNIQUE',summary:'Two people work together on the same change, sharing design thinking, coding and review in real time.',helps:'Spread context, improve design feedback and reduce knowledge bottlenecks.',steps:['Agree the goal and working rhythm.','Use driver/navigator or another shared-control pattern.','Switch roles regularly.','Reflect briefly on design and learning.'],example:'A specialist pairs with another engineer on a fragile settlement component during a real change.',watch:'Pairing is not one person typing while the other passively watches.'},
      {name:'Ensemble Programming',type:'TECHNIQUE',summary:'A small group works together on one problem with one shared workstream and rapid collective feedback.',helps:'Tackle complex or risky work while spreading understanding quickly.',steps:['Choose work where collective thinking is valuable.','Keep one active workstream visible to everyone.','Rotate the person controlling the keyboard.','Use short cycles and explicit breaks.'],example:'The team ensembles on a complex production defect to combine domain, test and architecture knowledge.',watch:'Do not use ensemble work for every task; apply it where learning and coordination benefits justify the cost.'},
      {name:'Technical Debt Impact Map',type:'CANVAS',summary:'Connect debt to visible delivery consequences such as delay, rework, incidents and risk.',helps:'Make technical debt discussable in product prioritisation.',steps:['Name the debt item or fragile area.','Capture recurring “interest payments”.','Estimate frequency and impact.','Choose whether to contain, reduce or deliberately accept it.'],example:'A brittle integration may add two days to every release and cause repeated incidents, making its cost visible beyond engineering frustration.',watch:'Do not create a giant debt inventory with no prioritisation logic.'}
    ],
    'built-in-quality':[
      {name:'Test Pyramid',type:'MODEL',summary:'A heuristic that favours many fast, focused lower-level tests and fewer slower end-to-end tests.',helps:'Create faster, more reliable feedback than an automation strategy dominated by UI tests.',steps:['Map current automated tests by level.','Identify slow, brittle feedback concentrated at the top.','Move appropriate checks closer to the code or service boundary.','Keep a smaller set of valuable end-to-end tests.'],example:'Business rules are verified with unit/service tests while only critical journeys remain in the UI suite.',watch:'Treat the pyramid as a heuristic, not a mandated ratio.'},
      {name:'Test-Driven Development',type:'TECHNIQUE',summary:'Use a short Red → Green → Refactor cycle to design behaviour through executable feedback.',helps:'Shorten feedback and encourage testable design.',steps:['Write a small failing test for desired behaviour.','Write the simplest code to make it pass.','Refactor while keeping tests green.','Repeat in small increments.'],example:'Add one failing example for a risk-rule edge case before implementing the rule.',watch:'TDD is a design/feedback practice, not merely writing tests first.'},
      {name:'Shift-Left Testing',type:'PRACTICE',summary:'Move useful quality feedback earlier in discovery, design and development.',helps:'Reduce the cost and queueing created by downstream defect discovery.',steps:['Identify where defects are first detected today.','Ask which checks can happen earlier.','Automate repeatable feedback where useful.','Keep independent later-stage validation for risks that require it.'],example:'Security scanning and API-contract checks run during CI instead of only before release.',watch:'Shift-left should not mean “QA does more work earlier”; quality remains a team responsibility.'}
    ],
    'architecture-autonomy':[
      {name:'Architecture Dependency Map',type:'CANVAS',summary:'Map which components, teams and approvals a typical change must cross.',helps:'Expose technical coupling as waiting and coordination cost.',steps:['Choose one representative feature.','Trace every component and team it touches.','Mark hand-offs, shared data and coordinated-release points.','Prioritise the highest-frequency/highest-impact coupling.'],example:'A portfolio change touching four services and three teams reveals where architecture creates recurring coordination.',watch:'Map real change paths, not an idealised architecture diagram.'},
      {name:"Conway's Law Lens",type:'MODEL',summary:'Use the idea that system structures tend to reflect communication structures to explore architecture and team boundaries together.',helps:'Ask whether organisational design and technical design reinforce unwanted dependencies.',steps:['Observe recurring communication/coordination paths.','Compare them with component/service boundaries.','Identify where ownership is split or unclear.','Experiment with clearer boundaries or team interaction patterns.'],example:'If every feature requires three teams to coordinate around one shared component, the architecture and team design may be reinforcing each other.',watch:'Conway’s Law is a lens, not a deterministic formula.'},
      {name:'Contract Testing',type:'TECHNIQUE',summary:'Automate expectations between services so teams can change independently with faster feedback.',helps:'Reduce integration waiting and coordinated testing.',steps:['Define the consumer/provider behaviour that must remain compatible.','Automate the contract check.','Run it in each team’s delivery pipeline.','Treat breaking contracts as visible change requiring coordination.'],example:'A consumer verifies the pricing API contract without waiting for a shared end-to-end environment.',watch:'Contract tests complement—not replace—other integration and production feedback.'}
    ],
    'small-batches-ci':[
      {name:'Trunk-Based Development',type:'PRACTICE',summary:'Keep branches short-lived and integrate frequently into a shared mainline.',helps:'Reduce divergence, merge risk and late integration surprises.',steps:['Measure current branch lifetime.','Shrink branch duration progressively.','Keep changes small and guarded where necessary.','Strengthen automated feedback on every integration.'],example:'A team moves from two-week feature branches to daily integration behind feature flags.',watch:'Frequent integration requires trustworthy automated feedback.'},
      {name:'Feature Flags',type:'TECHNIQUE',summary:'Decouple code integration from user exposure by controlling when a capability is enabled.',helps:'Integrate incomplete work safely and support progressive rollout.',steps:['Introduce the flag around the smallest useful behaviour.','Integrate code continuously.','Enable for controlled users/environments.','Remove stale flags once the decision is permanent.'],example:'A new onboarding flow is integrated early but enabled first for internal users.',watch:'Flags create complexity if they accumulate without ownership and cleanup.'},
      {name:'Branch Lifetime Check',type:'TOOL',summary:'Track how long branches remain divergent from the mainline.',helps:'Turn integration risk into visible data.',steps:['Capture branch age.','Compare age with merge issues or review delays.','Set an experiment to reduce typical lifetime.','Review whether integration feedback improves.'],example:'Median branch age drops from six days to one day while merge conflicts fall.',watch:'Do not turn the metric into a developer performance target.'}
    ],
    'continuous-delivery':[
      {name:'Deployment Pipeline',type:'MODEL',summary:'Visualise the automated path from code change through verification to a releasable or deployed state.',helps:'Expose slow, manual or unreliable delivery steps.',steps:['Map build, test, security, approval and deployment stages.','Capture wait and failure at each stage.','Automate repeatable evidence where safe.','Improve the slowest or least reliable feedback first.'],example:'A manual regression gate is replaced with automated evidence plus targeted exploratory testing.',watch:'Automation should improve evidence and reliability, not simply automate waste.'},
      {name:'Progressive Delivery',type:'TECHNIQUE',summary:'Expose a change gradually while watching evidence and preserving the ability to stop or roll back.',helps:'Reduce release risk and learn from real behaviour sooner.',steps:['Define the population or traffic slice.','Choose health and outcome signals.','Roll out incrementally.','Pause, roll back or expand based on evidence.'],example:'Release to internal users, then 5% of customers, before full rollout.',watch:'Progressive delivery needs observability and clear stop conditions.'},
      {name:'Observability Feedback Loop',type:'MODEL',summary:'Connect deployment to production signals, diagnosis, learning and adaptation.',helps:'Make real system behaviour part of product and engineering feedback.',steps:['Define signals that indicate user and system health.','Make them accessible to the team.','Review after meaningful changes.','Turn recurring findings into product or engineering decisions.'],example:'A release is judged using error rate, latency and customer-completion data rather than deployment success alone.',watch:'Collecting telemetry is not the same as learning from it.'}
    ],
    'ai-assisted-engineering':[
      {name:'Constraint Migration Map',type:'MODEL',summary:'When AI accelerates one step, map where waiting and workload move next across review, test, integration and release.',helps:'Prevent “AI productivity” from being measured only at code creation.',steps:['Map the delivery steps end to end.','Compare throughput/wait before and after AI adoption.','Identify the queue that grew.','Improve or limit upstream work to protect flow.'],example:'Code generation triples, but review time doubles—showing the bottleneck moved from coding to review.',watch:'Local acceleration is not system improvement unless value moves faster.'},
      {name:'AI Delivery Flow Check',type:'CANVAS',summary:'Assess AI adoption through flow, quality, learning and downstream capacity.',helps:'Create a balanced AI experiment instead of chasing usage metrics.',steps:['Choose one AI-assisted workflow.','Capture baseline lead time, review time, defects and rework.','Run the experiment with bounded WIP.','Compare end-to-end evidence, not lines generated.'],example:'A team measures idea-to-production time and review queue after introducing a coding assistant.',watch:'Adoption rate is not an outcome.'}
    ],
    'human-ai-quality':[
      {name:'Human-in-the-Loop Review',type:'TECHNIQUE',summary:'Require meaningful human judgment at consequential points in an AI-assisted workflow.',helps:'Keep accountability and contextual reasoning where automation is uncertain or high impact.',steps:['Define what the AI may generate or propose.','Define the evidence the reviewer must inspect.','Make the human decision explicit.','Record exceptions and improve guardrails.'],example:'Generated code cannot merge until a reviewer can explain the change, verify tests and confirm data/security boundaries.',watch:'A ceremonial approval click is not meaningful human oversight.'},
      {name:'AI Definition of Done',type:'CANVAS',summary:'Extend team quality standards for AI-assisted work.',helps:'Make verification expectations explicit and repeatable.',steps:['List AI use cases used by the team.','Define required review, tests and security checks.','Define prohibited data/code exposure.','Add the standards to the team’s Definition of Done or working agreement.'],example:'AI-generated changes require independent tests and a reviewer who understands the implementation.',watch:'Keep the standard proportionate to consequence and update it as tools change.'}
    ],
    'ai-agents-autonomy':[
      {name:'Agent Autonomy Tiers',type:'MODEL',summary:'Classify agent actions as Suggest → Prepare → Execute with Approval → Execute Autonomously.',helps:'Match autonomy to consequence rather than granting broad permissions by default.',steps:['List actions the agent may take.','Classify impact/reversibility.','Assign the highest safe autonomy tier for each action.','Review when capability or risk changes.'],example:'An agent may draft a pull request autonomously but production deployment requires explicit human approval.',watch:'Autonomy is contextual; the same action may need different controls in test and production.'},
      {name:'Permission × Impact Matrix',type:'CANVAS',summary:'Map agent permissions against potential business, security and operational impact.',helps:'Apply least privilege and choose guardrails.',steps:['List tools, systems and data the agent can access.','Estimate impact if each permission is misused.','Remove or narrow unnecessary permissions.','Add approval, isolation or monitoring where impact is high.'],example:'Read-only access to logs may be low risk; write access to production customer data is high impact and tightly controlled.',watch:'Convenience is not a sufficient reason for broad permissions.'},
      {name:'Kill Switch & Rollback',type:'CONTROL',summary:'Design how to stop an agent and reverse harmful actions before giving it meaningful autonomy.',helps:'Make failure recoverable.',steps:['Identify stop conditions.','Provide a reliable way to revoke or halt execution.','Preserve audit evidence.','Test rollback/recovery before relying on it.'],example:'A deployment agent can be disabled immediately and the previous release restored automatically.',watch:'A kill switch that has never been tested is only a hope.'}
    ],
    'knowledge-dependencies':[
      {name:'Knowledge Risk Map',type:'TOOL',summary:'Map critical areas against how many people can safely change or support them.',helps:'Prioritise capability risks hidden behind individual expertise.',steps:['List critical systems/capabilities.','Count people who can independently work in each area.','Add business/operational criticality.','Prioritise high-criticality, low-coverage areas.'],example:'A settlement engine supported by one specialist ranks above a low-risk internal tool with the same coverage.',watch:'The number is a risk signal, not a target for judging individuals.'},
      {name:'Pairing & Rotation',type:'TECHNIQUE',summary:'Spread technical context through real work rather than relying only on documentation.',helps:'Reduce queues around experts while preserving deep expertise.',steps:['Choose one high-risk knowledge area.','Pair another person through a real change.','Rotate recurring maintenance/support responsibility.','Review whether independent capability increased.'],example:'A second engineer pairs on the next three changes until they can handle routine work with light support.',watch:'Create capacity for learning; do not simply add teaching work to an already overloaded specialist.'}
    ],

    'dependency-constraint':[
      {name:'Dependency Type Map',type:'MODEL',summary:'Classify dependencies as competency, architecture, process, decision, authorization, external team, vendor/third party or environment/tooling/data.',helps:'Give teams language for recurring constraints instead of treating everything as “blocked”.',steps:['List recurring waits.','Classify each by dependency type.','Look for repeated patterns across work.','Use the pattern to choose the right conversation.'],example:'Repeated production-deployment waiting may be an authorization dependency rather than a team-efficiency problem.',watch:'Classification is useful only if it leads to better action.'},
      {name:'Control · Influence · Escalate · Accept/Manage',type:'FRAMEWORK',summary:'Choose a response based on what the team can change directly, shape with others, raise systemically or consciously manage.',helps:'Stop teams from either owning everything or feeling powerless.',steps:['Ask whether the team can remove or reduce the dependency itself.','If not, ask whether collaboration can improve it.','If authority sits elsewhere, escalate with evidence.','If legitimate for now, make the constraint predictable and manageable.'],example:'Specialist knowledge may be controlled through pairing; architecture approval may require escalation; regulatory sign-off may need to be managed deliberately.',watch:'“Accept” does not mean ignore. It means consciously design around a legitimate constraint.'},
      {name:'Dependency Heatmap',type:'TOOL',summary:'Prioritise dependencies using Frequency × Impact × Wait.',helps:'Focus attention on consequential constraints instead of the longest complaint list.',steps:['Score frequency 1–5.','Score impact 1–5.','Score wait 1–5.','Multiply for an exposure score and discuss the highest items first.'],example:'Architecture approval: 4 × 5 × 4 = 80, making it a strong candidate for system-level attention.',watch:'The score is a prioritisation aid, not a scientific metric.'},
      {name:'Dependency Investigation Canvas',type:'CANVAS',summary:'Capture what is being waited for, why it exists, impact, evidence and the chosen response.',helps:'Move from frustration to evidence and action.',steps:['Name the dependency and who/what the team waits for.','Capture why it exists, frequency, wait and consequence.','Classify the response.','Agree an action, owner, evidence and review date.'],example:'A recurring test-data delay is documented with blocked days, affected items and an experiment to create self-service data.',watch:'Keep the canvas lightweight enough to support conversation rather than bureaucracy.',internalHref:'dependency-coaching.html',internalLabel:'Open full Dependency Coaching toolkit →'}
    ],
    'flow-bottleneck':[
      {name:'Theory of Constraints',type:'FRAMEWORK',summary:'Improve the whole system by focusing on the constraint that limits overall throughput.',helps:'Avoid spending improvement effort on non-bottlenecks.',steps:['Identify the current constraint.','Exploit it: protect and use it effectively.','Subordinate upstream/downstream work to the constraint.','Elevate the constraint if needed.','Repeat because the bottleneck can move.'],example:'If testing is the constraint, producing more development output may worsen the queue; the system should protect testing capacity and reduce incoming WIP.',watch:'The current bottleneck is not permanent.'},
      {name:'Bottleneck Map',type:'CANVAS',summary:'Visualise workflow steps and persistent queues between them.',helps:'See where work accumulates rather than where people appear busiest.',steps:['Draw the real workflow.','Count active and waiting work at each step.','Mark persistent queues and wait time.','Run one experiment on the strongest constraint.'],example:'A queue of eight items before security review is more informative than utilisation percentages.',watch:'Use data across time; today’s temporary pile-up may not be the true bottleneck.'}
    ],
    'wip-queues':[
      {name:'WIP Limits',type:'PRACTICE',summary:'Limit how much work can be active in a workflow state so finishing is favoured over starting.',helps:'Reduce multitasking, expose blockers and shorten feedback.',steps:['Visualise current WIP by state.','Set an initial limit based on current capability.','When the limit is reached, swarm or solve the blocker instead of starting more.','Adjust the limit based on evidence.'],example:'If Test is at its WIP limit, developers help resolve testing or defects rather than pulling a new story.',watch:'WIP limits without support to resolve constraints can feel punitive.'},
      {name:'Aging WIP',type:'TOOL',summary:'Track how long active items have been in progress.',helps:'Spot flow risk before work becomes a missed commitment.',steps:['Record start age for active items.','Highlight items older than normal cycle-time expectations.','Ask what is preventing completion.','Swarm or remove the constraint.'],example:'A story aging at 12 days in a system where most finish in five becomes an explicit coaching signal.',watch:'Age is a conversation trigger, not a reason to blame the item owner.'}
    ],
    'empiricism-feedback':[
      {name:'Transparency → Inspection → Adaptation',type:'MODEL',summary:'Empirical control depends on making relevant reality visible, inspecting it frequently and changing course when evidence requires it.',helps:'Turn reviews and metrics into decision loops instead of reporting rituals.',steps:['Make the work/outcome/risk transparent enough to inspect.','Inspect at a cadence appropriate to uncertainty.','Identify what the evidence means.','Adapt product, plan, process or behaviour.'],example:'A Sprint Review reveals low usage of a released capability, leading to a product hypothesis change rather than simply acknowledging the metric.',watch:'Inspection without adaptation is reporting, not empiricism.'},
      {name:'Feedback Loop Map',type:'CANVAS',summary:'Map Action → Signal → Sensemaking → Decision → Adaptation and the delay between each step.',helps:'Find feedback that arrives too late to influence decisions.',steps:['Choose one important decision.','Trace where evidence comes from.','Measure time from action to evidence and from evidence to decision.','Shorten the slowest useful loop.'],example:'Customer feedback arrives six weeks after release; moving user testing earlier may reduce decision latency.',watch:'Faster feedback is useful only when someone can act on it.'}
    ],
    'change-transformation':[
      {name:'Change Principles',type:'FRAMEWORK',summary:'A practical set of principles: Blend Don’t Bulldoze, Pace Before Race, Build Capability, Start with a Slice, Show Evidence, Build Change Champions, Fit the Context, Learn from Failure, Celebrate Progress, Make Leadership Visible, Keep the Feedback Loop Open.',helps:'Keep transformation adaptive and context-sensitive.',steps:['Choose the principle most relevant to the current change risk.','Translate it into one observable behaviour or experiment.','Gather evidence.','Scale only when the system shows readiness.'],example:'Instead of mandating a process across 20 teams, start with two teams, show evidence and adapt before expanding.',watch:'Principles guide judgment; they are not a new compliance checklist.'},
      {name:'Slice Strategy',type:'TECHNIQUE',summary:'Test a transformation idea in a bounded slice before scaling.',helps:'Create evidence and learning with lower organisational risk.',steps:['Choose a representative but manageable slice.','Define the constraint/outcome to improve.','Run the change with a review date.','Scale, adapt or stop based on evidence.'],example:'Pilot a new discovery/delivery operating pattern in one value stream for 30 days before enterprise rollout.',watch:'Choose a slice that can teach you something meaningful, not only the easiest team.'},
      {name:'Change Champions',type:'TECHNIQUE',summary:'Build internal peers who can model, translate and sustain the change within local context.',helps:'Reduce dependence on a central transformation team.',steps:['Identify credible local practitioners.','Build capability through real work.','Give them room to adapt within clear intent.','Connect champions to share learning across teams.'],example:'Experienced Scrum Masters co-design experiments and coach neighbouring teams instead of merely repeating central messaging.',watch:'Do not turn champions into unpaid rollout coordinators with no authority or capacity.'}
    ],
    'resistance-change':[
      {name:'Four Types of Resistors',type:'MODEL',summary:'A practitioner model distinguishing patterns such as Skeptics, Saboteurs, Diehards and Followers so the coach can explore why resistance occurs.',helps:'Differentiate questioning, active opposition, entrenched belief and social following instead of treating all resistance as the same.',steps:['Observe whether resistance is active/passive and what seems to drive it.','Form a hypothesis about the pattern.','Ask questions to understand evidence, identity, incentives and history.','Choose an engagement strategy based on the reason, not the label.'],example:'A Skeptic may need credible evidence and participation; a Follower may simply be aligning with a powerful local voice.',watch:'Never use the labels to categorise “bad people”. They are prompts for inquiry.'},
      {name:'Resistance Interview',type:'TECHNIQUE',summary:'Use structured curiosity to surface what a person is protecting, fearing or doubting.',helps:'Turn resistance into design information.',steps:['Ask what concerns them about the change.','Ask what they believe could be lost or harmed.','Ask what evidence or condition would increase confidence.','Reflect back what should influence the change design.'],example:'A tester resisting automation may be protecting regulatory evidence quality rather than resisting automation itself.',watch:'Listening is not a promise that every concern will change the decision.'}
    ],
    'communication-decision-flow':[
      {name:'Communication Richness Ladder',type:'MODEL',summary:'Match communication channel richness to ambiguity and interaction need instead of assuming one channel is always best.',helps:'Choose async or synchronous communication intentionally.',steps:['Identify whether the need is to inform, align, decide or resolve conflict.','Estimate ambiguity and emotional stakes.','Choose a channel with enough interaction and feedback.','Capture the decision afterwards.'],example:'Stable status information can be asynchronous; a high-stakes architecture conflict needs richer synchronous dialogue.',watch:'Face-to-face is not automatically superior; accessibility and context matter.'},
      {name:'Decision Log',type:'TOOL',summary:'Record consequential decisions, owner, rationale, date and review conditions.',helps:'Reduce repeated debates and invisible decision history.',steps:['Record the decision and accountable owner.','Capture the key rationale/trade-off.','Link evidence or constraints.','State when the decision should be revisited.'],example:'A decision to accept a temporary dependency is logged with a review date after a platform migration.',watch:'Keep logs lightweight and searchable; a decision archive nobody reads creates no value.'}
    ],
    'experiment-improvement':[
      {name:'Hypothesis → Experiment → Evidence → Adapt',type:'FRAMEWORK',summary:'Structure continuous improvement as an explicit learning loop.',helps:'Prevent actions from becoming permanent without evidence.',steps:['State the hypothesis about the problem.','Run the smallest useful experiment.','Observe agreed evidence.','Keep, adapt or stop based on what happened.'],example:'Hypothesis: WIP causes long review queues → experiment: limit active PRs → evidence: review time and aging → adapt after two weeks.',watch:'An experiment without a review decision is just a temporary change.'},
      {name:'Improvement Experiment Canvas',type:'CANVAS',summary:'Capture belief, action, evidence, owner and review date for one improvement experiment.',helps:'Limit improvement WIP and make learning reviewable.',steps:['Write the problem belief.','Describe the small change.','Define evidence and baseline.','Assign owner and review date.'],example:'A retrospective action becomes a two-Sprint experiment with explicit success/failure evidence.',watch:'Keep one or two meaningful experiments active instead of a backlog of forgotten actions.'}
    ]
  };

  const modal=document.getElementById('topicModal');
  if(!modal)return;
  const panel=modal.querySelector('.topic-modal-panel');
  const progress=modal.querySelector('.topic-progress');
  const slideWrap=modal.querySelector('.topic-slide-wrap');
  const footer=modal.querySelector('.topic-modal-footer');
  const modalTitle=document.getElementById('topicModalTitle');
  let activeTopicId=null,activeTechniqueIndex=null;

  const esc=s=>String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
  const methodsLabel=count=>`${count} ${count===1?'METHOD / MODEL':'METHODS & MODELS'}`;

  const bar=document.createElement('div');
  bar.className='topic-method-bar';
  bar.hidden=true;
  bar.innerHTML='<div><span class="topic-method-icon">🧰</span><span id="topicMethodCount"></span><small>Models, techniques, canvases & tools</small></div><button class="topic-method-open" type="button">Explore techniques →</button>';
  progress.insertAdjacentElement('beforebegin',bar);

  const stage=document.createElement('section');
  stage.className='technique-stage';stage.hidden=true;
  stage.innerHTML='<div class="technique-stage-head"><div><span class="technique-kicker">LEARN → THINK → PRACTICE → USE</span><h3 id="techniqueStageTitle">Techniques & Models</h3><p id="techniqueStageIntro"></p></div><button class="technique-close" type="button" aria-label="Return to topic">×</button></div><div class="technique-stage-body" id="techniqueStageBody"></div>';
  progress.insertAdjacentElement('afterend',stage);

  const countEl=bar.querySelector('#topicMethodCount');
  const openBtn=bar.querySelector('.topic-method-open');
  const closeBtn=stage.querySelector('.technique-close');
  const stageTitle=stage.querySelector('#techniqueStageTitle');
  const stageIntro=stage.querySelector('#techniqueStageIntro');
  const stageBody=stage.querySelector('#techniqueStageBody');

  function syncTopic(id){
    activeTopicId=id;
    activeTechniqueIndex=null;
    const items=library[id]||[];
    bar.hidden=!items.length;
    if(items.length)countEl.textContent=methodsLabel(items.length);
    if(stage&&!stage.hidden)closeStage();
  }

  function renderList(){
    const items=library[activeTopicId]||[];
    activeTechniqueIndex=null;
    stageTitle.textContent=`Techniques for ${modalTitle.textContent||'this topic'}`;
    stageIntro.textContent='Choose a model, technique, canvas or tool to understand how to apply it in coaching.';
    stageBody.innerHTML=`<div class="technique-grid">${items.map((t,i)=>`<button class="technique-card" type="button" data-technique-index="${i}"><span class="technique-type ${esc(t.type.toLowerCase().replace(/[^a-z]+/g,'-'))}">${esc(t.type)}</span><h4>${esc(t.name)}</h4><p>${esc(t.summary)}</p><b>Learn this ${esc(t.type.toLowerCase())} →</b></button>`).join('')}</div>${activeTopicId==='dependency-constraint'?'<div class="technique-toolkit-note"><strong>Need the full facilitation toolkit?</strong><span>The detailed Dependency & Constraint Coaching page includes the canvas, heatmap, session guide and downloadable Excel workbook.</span><a href="dependency-coaching.html">Open full Dependency Coaching toolkit →</a></div>':''}`;
    stageBody.querySelectorAll('[data-technique-index]').forEach(btn=>btn.addEventListener('click',()=>renderDetail(Number(btn.dataset.techniqueIndex))));
  }

  function renderDetail(i){
    const t=(library[activeTopicId]||[])[i];if(!t)return;
    activeTechniqueIndex=i;
    stageTitle.textContent=t.name;
    stageIntro.textContent=t.summary;
    const model=t.model&&t.model.length?`<div class="technique-model-flow">${t.model.map((x,n)=>`${n?'<b>→</b>':''}<span>${esc(x)}</span>`).join('')}</div>`:'';
    stageBody.innerHTML=`<button class="technique-back" type="button">← All techniques</button><div class="technique-detail"><div class="technique-detail-top"><span class="technique-type ${esc(t.type.toLowerCase().replace(/[^a-z]+/g,'-'))}">${esc(t.type)}</span><div><small>BEST FOR</small><strong>${esc(t.helps)}</strong></div></div>${model}<section><h4>How to use it</h4><ol>${t.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol></section><section class="technique-example"><h4>Example</h4><p>${esc(t.example)}</p></section><section class="technique-watch"><h4>Watch for</h4><p>${esc(t.watch)}</p></section>${t.internalHref?`<a class="technique-internal-link" href="${esc(t.internalHref)}">${esc(t.internalLabel||'Open related Agile Orbit toolkit →')}</a>`:''}</div>`;
    stageBody.querySelector('.technique-back').addEventListener('click',renderList);
  }

  function openStage(){
    if(!activeTopicId||!(library[activeTopicId]||[]).length)return;
    stage.hidden=false;slideWrap.hidden=true;footer.hidden=true;progress.hidden=true;bar.hidden=true;renderList();
    stage.scrollTop=0;
  }
  function closeStage(){
    stage.hidden=true;slideWrap.hidden=false;footer.hidden=false;progress.hidden=false;
    const items=library[activeTopicId]||[];bar.hidden=!items.length;
    activeTechniqueIndex=null;
  }

  openBtn.addEventListener('click',openStage);closeBtn.addEventListener('click',closeStage);

  document.querySelectorAll('[data-topic]').forEach(card=>{
    const id=card.dataset.topic,items=library[id]||[];
    if(items.length){
      const count=document.createElement('span');count.className='topic-method-count';count.textContent=`🧰 ${methodsLabel(items.length)}`;
      const explore=card.querySelector('b');if(explore)explore.insertAdjacentElement('beforebegin',count);
    }
    card.addEventListener('click',()=>{syncTopic(id);setTimeout(()=>syncTopic(id),0)},true);
  });

  const observer=new MutationObserver(()=>{
    if(modal.hidden){activeTopicId=null;stage.hidden=true;slideWrap.hidden=false;footer.hidden=false;progress.hidden=false;bar.hidden=true;return}
    if(activeTopicId){const items=library[activeTopicId]||[];if(!stage.hidden)return;bar.hidden=!items.length;if(items.length)countEl.textContent=methodsLabel(items.length)}
  });
  observer.observe(modal,{attributes:true,attributeFilter:['hidden']});

  document.addEventListener('keydown',e=>{
    if(stage.hidden)return;
    if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();closeStage()}
    else if(e.key==='ArrowLeft'&&activeTechniqueIndex!==null){e.preventDefault();e.stopImmediatePropagation();renderList()}
  },true);
})();
